  else{
   foreach(['school','address','npsn','nss','email','number','subject','attachment','bank_destination','debit_account','debit_name','place','date','month','year','head_name','head_nip','head_ktp','head_phone','treasurer_name','treasurer_nip','treasurer_ktp','treasurer_phone','program','purpose','note'] as $key)$data[$key]=si_s($_POST[$key]??'', $key==='address'?400:255);
   $rawRecipients=$_POST['recipients']??[];$data['recipients']=[];
   if(!is_array($rawRecipients))$rawRecipients=[];
   foreach(array_slice($rawRecipients,0,100) as $row){
    if(!is_array($row))continue;
    $amountRaw=si_s($row['amount']??'',40);$amountClean=si_parse_amount($amountRaw);$amountValid=($amountClean!==null);
     $rec=['account'=>si_s($row['account']??'',100),'name'=>si_s($row['name']??'',180),'bank'=>si_s($row['bank']??'',100),'amount'=>$amountClean===null?'invalid':$amountClean,'note'=>si_s($row['note']??'',255)];
    if($rec['account']===''&&$rec['name']===''&&$rec['amount']===''&&$rec['note']==='')continue;
    if($rec['name']===''||$rec['account']===''||$rec['amount']===''||!is_numeric($rec['amount'])||(float)$rec['amount']<0||!$amountValid){$errors[]='Setiap penerima harus memiliki nama, nomor rekening, dan nominal rupiah berupa angka yang valid.';break;}
    $data['recipients'][]=$rec;
   }
   if(!$data['recipients'])$errors[]='Tambahkan sekurang-kurangnya satu penerima transfer.';
   if($data['recipients'] && !si_total_supported($data['recipients']))$errors[]='Total SI melebihi batas 15 digit atau format nominal tidak valid. Periksa nominal setiap penerima.';
   if($data['school']===''||$data['number']===''||$data['debit_account']===''||$data['debit_name']===''||$data['head_name']===''||$data['treasurer_name']==='')$errors[]='Lengkapi identitas sekolah, nomor surat, rekening sumber, nama pemilik rekening, kepala sekolah, dan bendahara.';
   if(!$errors){$_SESSION['spj_si_data']=$data;$saved=true;}
  }
 }
