<script>
(function(){
 const tbody=document.getElementById('recipientRows'),add=document.getElementById('addRecipient');
 function renumber(){[...tbody.querySelectorAll('tr')].forEach((tr,i)=>{tr.querySelector('.row-number').textContent=i+1;tr.querySelectorAll('input').forEach(inp=>{inp.name=inp.name.replace(/recipients\[\d+\]/,'recipients['+i+']');if(inp.name.endsWith('[bank]')&&!inp.value)inp.value='BJB';});});}
 add.addEventListener('click',()=>{if(tbody.querySelectorAll('tr').length>=100){alert('Maksimal 100 penerima.');return;}const i=tbody.querySelectorAll('tr').length;const tr=document.createElement('tr');tr.innerHTML='<td class="row-number">'+(i+1)+'</td><td><input name="recipients['+i+'][account]" placeholder="Nomor rekening / VA"></td><td><input name="recipients['+i+'][name]" placeholder="Nama penerima"></td><td><input name="recipients['+i+'][bank]" value="BJB" placeholder="Bank"></td><td><input name="recipients['+i+'][amount]" placeholder="Nominal" inputmode="decimal"></td><td><input name="recipients['+i+'][note]" placeholder="Keterangan"></td><td><button type="button" class="si-btn secondary remove-row">Hapus</button></td>';tbody.appendChild(tr);});
 tbody.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')){e.target.closest('tr').remove();renumber();}});
})();
</script>
